const base = 'https://api.ipma.pt/open-data/observation/seismic/';
return [[
    { url: base + '7.json', area: 7 },
    { url: base + '3.json', area: 3 }
]];

const rows = (msg.payload && msg.payload.data) || [];
if (!rows.length) {
    node.warn('IPMA: sem eventos (area ' + msg.area + ')');
    return null;
}
const ids = [];
const payloads = [];
for (const r of rows) {
    // sismoId vem quase sempre vazio -> id sintetico estavel (hora + coordenadas)
    const id = r.sismoId ? r.sismoId : `${r.time}_${r.lat}_${r.lon}`;
    ids.push(id);
    payloads.push(JSON.stringify(Object.assign({}, r, { _idArea: msg.area })));
}
msg.n = rows.length;
msg.query = `INSERT INTO raw_sismos (fonte, formato, id_externo, payload)
             SELECT 'IPMA', 'json', t.id, t.p
             FROM UNNEST($1::text[], $2::text[]) AS t(id, p)
             ON CONFLICT (fonte, id_externo) DO NOTHING`;
msg.params = [ids, payloads];
return msg;
